	out, _, code = runCLI(t, file, "waiver", "s1", "r1", "w1", "学科竞赛获奖")
	if code != 0 || !strings.Contains(out, "返回原申请") ||
		!strings.Contains(out, "状态：已撤销") {
		t.Fatalf("新申请生效后旧编号重试仍应显示已撤销，code=%d out=%q", code, out)
	}
