	}
	// 历史仍是各一行：旧申请未被改写，新申请仍是有效。
	out, _, _ = runCLI(t, file, "show", "s1")
	if strings.Count(out, "免修 w1：要求 r1") != 1 ||
		strings.Count(out, "免修 w2：要求 r1") != 1 ||
		!strings.Contains(out, `免修 w2：要求 r1，依据 "外校同层次课程"，状态：有效`) {
