			t.Fatalf("免修历史应完整保留 %q，out=%q", want, out)
		}
	}
	for _, line := range []string{"免修 w1：要求 r1", "免修 w2：要求 r1", "免修 w3：要求 r1"} {
		if strings.Count(out, line) != 1 {
			t.Fatalf("show 中 %q 应恰好出现一次，out=%q", line, out)
		}
	}
