		}
	}
	for _, line := range []string{"免修 w1：要求 r1", "免修 w2：要求 r1"} {
		if strings.Count(out, line) != 1 {
			t.Fatalf("show 中 %q 应恰好出现一次（不覆盖、不重复），out=%q", line, out)
		}
	}
}

